<template>
	<div class="page-login">
		<div class="page-login--layer page-login--layer-area">
			<ul class="circles">
				<li v-for="n in 10" :key="n"></li>
			</ul>
		</div>
		<div class="page-login--layer page-login--layer-time" flex="main:center cross:center">
			{{time}}
		</div>
		<div class="page-login--layer">
			<div class="page-login--content" flex="dir:top main:justify cross:stretch box:justify">
				<div class="page-login--content-header">

				</div>
				<div class="page-login--content-main" flex="dir:top main:center cross:center">
					<!-- logo -->
					<!-- <img class="page-login--logo" src="../../../../public/preview@2x.png" /> -->
					<h2>简单进销存</h2>
					<!-- form -->
					<div class="page-login--form">

						<el-card shadow="never">
							<el-form ref="loginForm" label-position="top" :rules="rules" :model="formLogin" size="default">
								<el-form-item prop="username">
									<el-input type="text" v-model="formLogin.username" placeholder="用户名" clearable>
										<el-button slot="prepend" icon="el-icon-user"></el-button>
									</el-input>
								</el-form-item>
								<el-form-item prop="password">
									<el-input type="password" v-model="formLogin.password" placeholder="密码" clearable show-password>
										<el-button slot="prepend" icon="el-icon-key"></el-button>
									</el-input>
								</el-form-item>
								<el-form-item prop="code">

									<el-input type="text" placeholder="验证码" v-model="formLogin.code" clearable>
										<template slot="prepend">{{formLogin.code1}}+{{formLogin.code2}}=</template>
										<el-button slot="append" icon="el-icon-refresh" @click="refreshCode"></el-button>
									</el-input>


								</el-form-item>
								<img :src="formLogin.CodeID">
								<el-button size="default" @click="submit" type="primary" class="button-login" icon="el-icon-circle-check">
									登录
								</el-button>
								
								
							</el-form>
						</el-card>
						
					   <!-- <div>体验账号1:   zhangsan 密码aaa123</div>
						<div>体验账号2:   lisi 密码同上</div>
						<div>体验账号3:   wangwu 密码同上</div>
				 	    <div>(请不要修改密码，方便其他狐友体验)</div>
					 	<div>(谢谢)</div> --> 
						<!-- 						<p class="page-login--options" flex="main:justify cross:center">
							<span>
								<d2-icon name="question-circle" /> 忘记密码</span>
							<span>注册用户</span>
						</p> -->

					</div>
				</div>
				<div class="page-login--content-footer"> </div>
			</div>
		</div>

	</div>
</template>

<script>
	import dayjs from 'dayjs'
	import {
		mapActions
	} from 'vuex'
	import localeMixin from '@/locales/mixin.js'
	import {
		Query
	} from '@api/sys.login.js'
   import setter from '@/libs/setter'
	import {
		GetMenuTreeOnAuth
	} from '@api/sys.login.js'
	export default {
		mixins: [
			localeMixin
		],
		data() {
			return {
				timeInterval: null,
				time: dayjs().format('HH:mm:ss'),

				// 表单
				formLogin: {
					username: '',
					password: '',
					code: '',
					code1: 0,
					code2: 0,
					CodeID: ''
				},
				// 表单校验
				rules: {
					username: [{
						required: true,
						message: '请输入用户名',
						trigger: 'blur'
					}],
					password: [{
						required: true,
						message: '请输入密码',
						trigger: 'blur'
					}],
					code: [{
						required: true,
						message: '请输入验证码',
						trigger: 'blur'
					}]
				}
			}
		},
		mounted() {
			this.timeInterval = setInterval(() => {
				this.refreshTime()
			}, 1000)
			this.refreshCode()
		},
		beforeDestroy() {
			clearInterval(this.timeInterval)
		},
		methods: {
			...mapActions('d2admin/account', [
				'login'
			]),
			...mapActions('d2admin/menu', [
				'asideMenuSet'
			]),
			refreshTime() {
				this.time = dayjs().format('HH:mm:ss')
			},
			refreshCode() {
				this.formLogin.code1 = Math.round(Math.random() * 10);
				this.formLogin.code2 = Math.round(Math.random() * 10);
				this.formLogin.code = ''
			},

			/**
			 * @description 提交表单
			 */
			// 提交登录信息
			submit() {
				this.$refs.loginForm.validate((valid) => {
					if (valid) {
						if (parseInt(this.formLogin.code) === (this.formLogin.code1 + this.formLogin.code2)) {
							this.login({
									username: this.formLogin.username,
									//password: this.$md5(this.formLogin.password),
									password: this.formLogin.password,
									PlatForm: 'pc'
								})
								.then(() => {
									console.log('ok')
									let tj = ''
									GetMenuTreeOnAuth({
									username: this.formLogin.username,
									}).then(res => {
										
                                   if(this.formLogin.username){
				                   if(this.formLogin.username == 'admin'){
					                  tj = true
				                          }else{
											console.log(this.formLogin.username)
									//let gn = res.shuju.功能权限;
									let gn = res.data.功能权限
					                // console.log(res)
                                    let str = gn.toString();
									// console.log(str);
					                str = str.replace(/"/g,"'").replace('[','(').replace(']',')');
					                    tj = '二级菜单 in ' + str;
				                     }
			                      }
									
									// console.log(tj)
									// 初始化菜单			
									Query({
			                         tablename:'菜单',
			                          field:'fid',
			                          tj:tj   //加载条件										
									})
										.then(res => {
											
									const menus = res.data;
                                    let str = '';
                                    let menu1 = menus.filter(function(item,index){    //获取不重单
                                   if(item.一级菜单 != str){
                                   str = item.一级菜单;
                                    return item
			                        }
			                        })
									//console.log(menu1)
								let menu2 = [{ path: '/index', title: '首页', icon: 'home' },];
                                menu1.forEach(function(item,index){     //对一级菜单进行遍历
                                  let obj2 = {
	                              title:item.一级菜单,
	                              //path:item.path,
	                              icon: item.icon
								  //icon: ''
		                           };
	                              let arr2 = [];
	                              menus.forEach(function(v,i){        //再对其所属的二级菜单进行遍历
	                            if(v.一级菜单 == item.一级菜单 ){
	                                   if(v.二级菜单 !=''){
	                                   arr2.push({
									   title:v.二级菜单,						
									   path:v.path,
									   icon: ''
	                                })
		                        }

		                    }
		                    })
		                    obj2.children = arr2;
	                        menu2.push(obj2)
                            })
							console.log(menu2)
							let menux =	setter.uniarr(menu2,'title')
							console.log(menux)
									// this.asideMenuSet(menu) //把动态菜单持久化存储，不然刷新会没了
								
							this.asideMenuSet(menux) //把动态菜单持久化存储，不然刷新会没了			
										})
										.catch(err => {})
										}).catch(err => {})
									// 重定向对象不存在则返回顶层路径	
									this.$message.success('登陆成功')
									this.$router.replace(this.$route.query.redirect || '/')

								}).catch(err => {
									console.log(err)
									this.refreshCode()
								})
						} else {
							this.$message.error('验证码错误')
							this.refreshCode()
						}
					} else {
						// 登录表单校验失败
						this.$message.error('请输入账号/密码/验证码')
					}
				})
			}
		}
	}
</script>

<style lang="scss">
	.page-login {
		@extend %unable-select;
		$backgroundColor: #F0F2F5;
		// ---
		background-color: $backgroundColor;
		height: 100%;
		position: relative;

		// 层
		.page-login--layer {
			@extend %full;
			overflow: auto;
		}

		.page-login--layer-area {
			overflow: hidden;
		}

		// 时间
		.page-login--layer-time {
			font-size: 24em;
			font-weight: bold;
			color: rgba(0, 0, 0, 0.03);
			overflow: hidden;
		}

		// 登陆页面控件的容器
		.page-login--content {
			height: 100%;
			min-height: 500px;
		}

		// header
		.page-login--content-header {
			padding: 1em 0;

			.page-login--content-header-motto {
				margin: 0px;
				padding: 0px;
				color: $color-text-normal;
				text-align: center;
				font-size: 12px;
			}
		}

		// main
		.page-login--logo {
			width: 240px;
			margin-bottom: 2em;
			margin-top: -2em;
		}

		// 登录表单
		.page-login--form {
			width: 280px;

			// 卡片
			.el-card {
				margin-bottom: 15px;
			}

			// 登录按钮
			.button-login {
				width: 100%;
			}

			// 输入框左边的图表区域缩窄
			.el-input-group__prepend {
				padding: 0px 14px;
			}

			.login-code {
				height: 40px - 2px;
				display: block;
				margin: 0px -20px;
				border-top-right-radius: 2px;
				border-bottom-right-radius: 2px;
			}

			// 登陆选项
			.page-login--options {
				margin: 0px;
				padding: 0px;
				font-size: 14px;
				color: $color-primary;
				margin-bottom: 15px;
				font-weight: bold;
			}

			.page-login--quick {
				width: 100%;
			}
		}

		// 快速选择用户面板
		.page-login--quick-user {
			@extend %flex-center-col;
			padding: 10px 0px;
			border-radius: 4px;

			&:hover {
				background-color: $color-bg;

				i {
					color: $color-text-normal;
				}

				span {
					color: $color-text-normal;
				}
			}

			i {
				font-size: 36px;
				color: $color-text-sub;
			}

			span {
				font-size: 12px;
				margin-top: 10px;
				color: $color-text-sub;
			}
		}

		// footer
		.page-login--content-footer {
			padding: 1em 0;

			.page-login--content-footer-locales {
				padding: 0px;
				margin: 0px;
				margin-bottom: 15px;
				font-size: 12px;
				line-height: 12px;
				text-align: center;
				color: $color-text-normal;

				a {
					color: $color-text-normal;
					margin: 0 .5em;

					&:hover {
						color: $color-text-main;
					}
				}
			}

			.page-login--content-footer-copyright {
				padding: 0px;
				margin: 0px;
				margin-bottom: 10px;
				font-size: 12px;
				line-height: 12px;
				text-align: center;
				color: $color-text-normal;

				a {
					color: $color-text-normal;
				}
			}

			.page-login--content-footer-options {
				padding: 0px;
				margin: 0px;
				font-size: 12px;
				line-height: 12px;
				text-align: center;

				a {
					color: $color-text-normal;
					margin: 0 1em;
				}
			}
		}

		// 背景
		.circles {
			position: absolute;
			top: 0;
			left: 0;
			width: 100%;
			height: 100%;
			overflow: hidden;
			margin: 0px;
			padding: 0px;

			li {
				position: absolute;
				display: block;
				list-style: none;
				width: 20px;
				height: 20px;
				background: #FFF;
				animation: animate 25s linear infinite;
				bottom: -200px;

				@keyframes animate {
					0% {
						transform: translateY(0) rotate(0deg);
						opacity: 1;
						border-radius: 0;
					}

					100% {
						transform: translateY(-1000px) rotate(720deg);
						opacity: 0;
						border-radius: 50%;
					}
				}

				&:nth-child(1) {
					left: 15%;
					width: 80px;
					height: 80px;
					animation-delay: 0s;
				}

				&:nth-child(2) {
					left: 5%;
					width: 20px;
					height: 20px;
					animation-delay: 2s;
					animation-duration: 12s;
				}

				&:nth-child(3) {
					left: 70%;
					width: 20px;
					height: 20px;
					animation-delay: 4s;
				}

				&:nth-child(4) {
					left: 40%;
					width: 60px;
					height: 60px;
					animation-delay: 0s;
					animation-duration: 18s;
				}

				&:nth-child(5) {
					left: 65%;
					width: 20px;
					height: 20px;
					animation-delay: 0s;
				}

				&:nth-child(6) {
					left: 75%;
					width: 150px;
					height: 150px;
					animation-delay: 3s;
				}

				&:nth-child(7) {
					left: 35%;
					width: 200px;
					height: 200px;
					animation-delay: 7s;
				}

				&:nth-child(8) {
					left: 50%;
					width: 25px;
					height: 25px;
					animation-delay: 15s;
					animation-duration: 45s;
				}

				&:nth-child(9) {
					left: 20%;
					width: 15px;
					height: 15px;
					animation-delay: 2s;
					animation-duration: 35s;
				}

				&:nth-child(10) {
					left: 85%;
					width: 150px;
					height: 150px;
					animation-delay: 0s;
					animation-duration: 11s;
				}
			}
		}
	}
</style>

<vue-filename-injector>
export default function (Component) {
  Component.options.__source = "src/views/system/login/page.vue"
}
